sys_script_include.script:
var AllocatorUtils = Class.create();
AllocatorUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getAvailableBranches: function(current) {
        var available = [];

        var branchGR = new GlideRecord('x_1836478_cloud_0_branch');
        branchGR.addQuery('maximum_capacity', '>', 0);
        branchGR.query();

        while (branchGR.next()) {
            available.push(branchGR.getUniqueValue());
        }

        return 'sys_idIN' + available.join(',');
    },

    canUserAllocate: function() {
        // usuário atual (sys_id) e username (string)
        var userSysId = gs.getUserID();
        var userName = gs.getUserName();

        var allocationGR = new GlideRecord('x_1836478_cloud_0_allocation');

        // queremos apenas estados 2 (Awaiting for approval/payment) e 3 (Approved)
        allocationGR.addQuery('state', 'IN', '2,3');

        // criar condição: opened_by == userSysId OR sys_created_by == userName
        var qc = allocationGR.addQuery('opened_by', userSysId);
        qc.addOrCondition('sys_created_by', userName);

        allocationGR.query();

        // se achou algum registro, não pode alocar (retorna 'false'), senão 'true'
        return allocationGR.hasNext() ? 'false' : 'true';
    },


    type: 'AllocatorUtils'
});
